#include "deform_monitor_v3/risk_map/risk_map_publisher.hpp"
namespace deform_monitor_v3 { namespace risk_map {
static geometry_msgs::Point P(const Eigen::Vector3d&v){geometry_msgs::Point p;p.x=v.x();p.y=v.y();p.z=v.z();return p;}
static geometry_msgs::Vector3 V(const Eigen::Vector3f&v){geometry_msgs::Vector3 p;p.x=v.x();p.y=v.y();p.z=v.z();return p;}
ProbabilisticRiskMap BuildRiskMapMessage(const RiskMapFrame&f){ProbabilisticRiskMap m;m.header.stamp=f.stamp;m.header.frame_id=f.world_frame;m.schema_version=1;m.frame_index=f.frame_index;m.reference_epoch=f.reference_epoch;m.voxel_size=f.voxel_size;m.grid_origin=P(f.grid_origin_R);m.model_version=f.model_version;m.calibration_version=f.calibration_version;m.probabilities_calibrated=f.probabilities_calibrated;m.approximate_joint_model=f.approximate_joint_model;m.dropped_frame_count=f.dropped_frame_count;m.voxels.reserve(f.voxels.size());for(const auto&x:f.voxels){ProbabilisticRiskVoxel v;v.ix=x.key.x;v.iy=x.key.y;v.iz=x.key.z;v.center=P(x.center_R);v.p_deformation=x.p_deformation;v.p_novel_occupancy=x.p_novel_occupancy;v.decision_cost=x.decision_cost;v.deformation_log_odds=x.deformation_log_odds;v.novel_log_odds=x.novel_log_odds;v.log_bayes_factor_last=x.last_log_bayes_factor;v.visibility_probability=x.visibility_probability;v.principal_direction=V(x.principal_direction);v.direction_confidence=x.direction_confidence;v.knowledge_state=static_cast<uint8_t>(x.knowledge_state);v.event_semantics=static_cast<uint8_t>(x.semantics);v.region_id=x.region_id;m.voxels.push_back(v);}return m;}
ProbabilisticRiskRegions BuildRiskRegionsMessage(const RiskMapFrame&f){ProbabilisticRiskRegions m;m.header.stamp=f.stamp;m.header.frame_id=f.world_frame;m.schema_version=1;m.frame_index=f.frame_index;m.reference_epoch=f.reference_epoch;m.model_version=f.model_version;m.calibration_version=f.calibration_version;for(const auto&x:f.regions){ProbabilisticRiskRegion r;r.id=x.id;r.event_semantics=static_cast<uint8_t>(x.semantics);r.center=P(x.center_R);r.bbox_min=P(x.bbox_min_R);r.bbox_max=P(x.bbox_max_R);r.principal_direction.x=x.principal_direction_R.x();r.principal_direction.y=x.principal_direction_R.y();r.principal_direction.z=x.principal_direction_R.z();r.peak_deformation_probability=x.peak_deformation_probability;r.peak_novel_probability=x.peak_novel_probability;r.peak_decision_cost=x.peak_decision_cost;r.mean_decision_cost=x.mean_decision_cost;r.direction_confidence=x.direction_confidence;r.unknown_fraction=x.unknown_fraction;r.voxel_count=x.voxel_count;m.regions.push_back(r);}return m;}
} }
